  private int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}
  private int color(String s){return Color.parseColor(s);}
  private LinearLayout column(){LinearLayout v=new LinearLayout(this);v.setOrientation(1);return v;}
  private LinearLayout row(){LinearLayout v=new LinearLayout(this);v.setOrientation(0);return v;}
  private TextView label(String s,float size,int tint,boolean medium){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(tint);v.setFontFeatureSettings("tnum");v.setTypeface(Typeface.create(medium?"sans-serif-medium":"sans-serif",0));v.setIncludeFontPadding(false);v.setLineSpacing(dp(3),1);return v;}
  private GradientDrawable shape(int fill,int radius,boolean border){GradientDrawable d=new GradientDrawable();d.setColor(fill);d.setCornerRadius(dp(radius));if(border)d.setStroke(dp(1),outline);return d;}
  private Drawable ripple(int fill,int radius,boolean border){return new RippleDrawable(ColorStateList.valueOf(dark?0x33FFFFFF:0x226750A4),shape(fill,radius,border),shape(Color.WHITE,radius,false));}
  private Button button(String s,boolean filled,Runnable click){Button b=new Button(this);b.setText(s);b.setTextSize(14);b.setAllCaps(false);b.setTypeface(Typeface.create("sans-serif-medium",0));b.setTextColor(filled?onPrimary:primary);b.setBackground(ripple(filled?primary:Color.TRANSPARENT,24,!filled));b.setMinHeight(dp(48));b.setMinimumHeight(dp(48));b.setPadding(dp(16),dp(8),dp(16),dp(8));b.setStateListAnimator(null);b.setOnClickListener(v->click.run());return b;}
  private void addButton(LinearLayout parent,String s,boolean filled,Runnable action){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(12);parent.addView(button(s,filled,action),p);}
  private LinearLayout card(LinearLayout parent,int radius){LinearLayout c=column();c.setPadding(dp(20),dp(18),dp(20),dp(18));c.setBackground(shape(surface,radius,false));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(12);parent.addView(c,p);return c;}
  private void line(LinearLayout p,String s,int size,int tint,boolean medium,int bottom){LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(bottom);p.addView(label(s,size,tint,medium),lp);}
  private void title(String s,String subtitle){line(content,s,30,text,false,8);line(content,subtitle,13,muted,false,22);}
  private void showPage(String s){page=s;lastState="";scroll.scrollTo(0,0);render(true);}
  private void render(boolean force){JSONObject fresh=controller.state();String key=fresh.toString();if(!force&&key.equals(lastState))return;lastState=key;state=fresh;int y=scroll.getScrollY();content.removeAllViews();navigation.removeAllViews();refreshButton.setEnabled(!state.optBoolean("fetching"));nav("markets","行情",0);nav("sync","同步",1);nav("settings","設定",2);if(page.equals("markets"))markets();else if(page.equals("sync"))sync();else settings();scroll.post(()->scroll.scrollTo(0,y));}
  private void nav(String id,String name,int icon){boolean selected=page.equals(id);LinearLayout item=column();item.setGravity(Gravity.CENTER);item.setClickable(true);item.setFocusable(true);item.setContentDescription(name);item.setOnClickListener(v->showPage(id));FrameLayout capsule=new FrameLayout(this);capsule.setBackground(shape(selected?container:Color.TRANSPARENT,20,false));capsule.addView(new IconView(icon,selected?primary:muted),new FrameLayout.LayoutParams(dp(24),dp(24),Gravity.CENTER));item.addView(capsule,new LinearLayout.LayoutParams(dp(64),dp(32)));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-2,-2);cp.topMargin=dp(5);item.addView(label(name,12,selected?primary:muted,selected),cp);navigation.addView(item,new LinearLayout.LayoutParams(0,-1,1));}
  private JSONArray quotes(){return state.optJSONArray("quotes");}
  private int quoteColor(JSONObject q){if(q.optLong("time")==0)return muted;boolean red=state.optBoolean("redUp",true);double change=q.optDouble("percent",0);return change==0?muted:color(change>0?(red?(dark?"#FFB4AB":"#BA1A1A"):(dark?"#94D99A":"#146C2E")):(red?(dark?"#94D99A":"#146C2E"):(dark?"#FFB4AB":"#BA1A1A")));}
  private String number(JSONObject q,String key){if(!q.has(key)||q.isNull(key))return "—";double n=q.optDouble(key,Double.NaN);return Double.isFinite(n)?format(q,n,key.equals("percent")||key.equals("periodPercent")?2:q.optInt("priceDigits",2)):"—";}
  private String signed(JSONObject q,String key){String n=number(q,key);return n.equals("—")?n:(q.optDouble(key)>0?"+":"")+n;}
  private String time(long ms){return ms<=0?"尚未更新":new SimpleDateFormat("MM/dd HH:mm",Locale.TAIWAN).format(new Date(ms));}
  private String session(JSONObject q){return !q.optString("error").isEmpty()?(q.optLong("time")>0?"快取 · 更新失敗":"尚無報價"):q.optString("session","行情可能延遲");}
  private JSONObject newQuote(int sign){JSONObject q=new JSONObject();try{q.put("time",1).put("percent",sign);}catch(Exception ignored){}return q;}
  private void markets(){
    title("全球市場",controller.repo.instruments().size()+" 個指數與自選項目 · 行情可能延遲");JSONArray all=quotes();int up=0,down=0,valid=0;for(int i=0;i<all.length();i++){JSONObject q=all.optJSONObject(i);if(q.optLong("time")>0){valid++;if(q.optDouble("percent")>0)up++;else if(q.optDouble("percent")<0)down++;}}
    LinearLayout summary=card(content,24);line(summary,"關注項目漲跌分布",13,muted,true,14);LinearLayout breadth=row();breadth.addView(label(up+" 上漲",26,quoteColor(newQuote(1)),true),new LinearLayout.LayoutParams(0,-2,1));breadth.addView(label(down+" 下跌",26,quoteColor(newQuote(-1)),true),new LinearLayout.LayoutParams(0,-2,1));summary.addView(breadth);line(summary,valid+" 個有報價項目 · 各市場交易時間不同",12,muted,false,0);line(summary,"手機更新 "+time(state.optLong("lastFetch")),12,muted,false,0);
    HorizontalScrollView filterScroll=new HorizontalScrollView(this);filterScroll.setHorizontalScrollBarEnabled(false);LinearLayout filters=row();for(String r:new String[]{"全部","自選","亞太","美洲","歐洲","非洲"}){Button chip=button((region.equals(r)?"✓ ":"")+r,false,()->{region=r;render(true);});chip.setTextSize(12);chip.setBackground(ripple(region.equals(r)?container:Color.TRANSPARENT,12,true));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,dp(38));p.rightMargin=dp(6);filters.addView(chip,p);}filterScroll.addView(filters);LinearLayout.LayoutParams fp=new LinearLayout.LayoutParams(-1,dp(48));fp.bottomMargin=dp(8);content.addView(filterScroll,fp);line(content,state.optString("fetchStatus"),12,muted,false,12);
    for(int i=0;i<all.length();i++){JSONObject q=all.optJSONObject(i);String r=q.optString("region");if(!region.equals("全部")&&!(region.equals("自選")?controller.repo.isCustom(q.optString("symbol")):(region.equals("亞太")?(r.equals("亞洲")||r.equals("亞太")):region.equals(r))))continue;marketRow(q);}line(content,"Yahoo Finance 公開行情介面 · 非官方 API\n漲跌以前收盤為基準。點選指數查看報價時間與走勢。",11,muted,false,0);
  }
  private void marketRow(JSONObject q){LinearLayout c=row();c.setGravity(Gravity.CENTER_VERTICAL);c.setPadding(dp(16),dp(16),dp(16),dp(16));c.setMinimumHeight(dp(82));c.setBackground(ripple(surface,16,false));c.setContentDescription(q.optString("name")+" "+number(q,"value")+" "+signed(q,"percent")+"%");c.setClickable(true);c.setFocusable(true);c.setOnClickListener(v->openDetail(q));LinearLayout name=column();line(name,q.optString("name"),15,text,true,5);line(name,q.optString("region")+" · "+session(q),11,muted,false,0);c.addView(name,new LinearLayout.LayoutParams(0,-2,1));LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(dp(42),dp(28));sp.leftMargin=dp(5);sp.rightMargin=dp(12);c.addView(new SparkView(q,false),sp);LinearLayout values=column();values.setGravity(Gravity.END);values.addView(label(number(q,"value"),17,text,true));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-2,-2);cp.topMargin=dp(5);values.addView(label(signed(q,"percent")+(q.optLong("time")>0?"%":""),13,quoteColor(q),true),cp);c.addView(values);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(8);content.addView(c,p);}
  private void sync(){
    title("手環同步","中國版 Band 10 Pro ＋ Android");LinearLayout phone=card(content,24);line(phone,"手機行情",14,primary,true,12);line(phone,state.optString("fetchStatus"),18,text,true,8);line(phone,"最近更新 "+time(state.optLong("lastFetch")),12,muted,false,0);Button refresh=button(state.optBoolean("fetching")?"正在取得行情…":"更新行情並同步",true,()->controller.refresh());refresh.setEnabled(!state.optBoolean("fetching"));LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,-2);bp.topMargin=dp(16);phone.addView(refresh,bp);
    LinearLayout band=card(content,24);line(band,"手環連線",14,primary,true,12);line(band,state.optString("bridgeStatus"),17,text,true,10);line(band,"最近收到手環確認 "+time(state.optLong("lastAck")),12,muted,false,0);JSONArray devices=state.optJSONArray("devices");if(devices!=null&&devices.length()>1){String[] names=new String[devices.length()+1];names[0]="選擇手環";int selected=0;for(int i=0;i<devices.length();i++){JSONObject d=devices.optJSONObject(i);names[i+1]=d.optString("name");if(d.optString("id").equals(state.optString("device")))selected=i+1;}Spinner picker=spinner(names,selected);picker.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int pos,long id){if(pos>0){String target=devices.optJSONObject(pos-1).optString("id");if(!target.equals(state.optString("device")))controller.action("device",target);}}});band.addView(picker);}
    Button send=button(state.optBoolean("sending")?"等待手環確認…":"連接並傳送現有行情",true,()->controller.connectAndSync());send.setEnabled(!state.optBoolean("sending")&&!state.optBoolean("connecting"));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(16);band.addView(send,p);addButton(band,"授權手環通訊",false,()->controller.authorize(this));addButton(band,"安裝手環端程式",false,()->installBand());addButton(band,"開啟小米運動健康",false,()->openFitness());LinearLayout help=card(content,24);line(help,"首次使用",18,text,true,12);line(help,"1  在小米運動健康完成配對\n\n2  安裝手環端程式並在手環開啟\n\n3  授權手環通訊，再更新行情",14,muted,false,14);line(help,"安裝完成後退出 AstroBox，讓小米運動健康重新連上手環。手機收到「手環已確認收到」才代表同步完成。",12,muted,false,0);
  }
  private Spinner spinner(String[] entries,int selected){Spinner s=new Spinner(this);ArrayAdapter<String> a=new ArrayAdapter<>(this,android.R.layout.simple_spinner_item,entries);a.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);s.setAdapter(a);s.setSelection(selected,false);s.setMinimumHeight(dp(52));s.setPopupBackgroundDrawable(shape(surface,16,false));return s;}
  private void settings(){
    title("設定","偏好設定會在下次同步時套用到手環");LinearLayout preferences=card(content,24);line(preferences,"更新與顯示",16,text,true,12);line(preferences,"背景更新間隔",14,text,true,6);line(preferences,"由 Android 排程，可能因省電而延後",12,muted,false,4);final int[] intervals={0,15,30,60};int selected=0;for(int i=0;i<intervals.length;i++)if(state.optInt("interval")==intervals[i])selected=i;Spinner interval=spinner(new String[]{"僅手動更新","每 15 分鐘","每 30 分鐘","每 60 分鐘"},selected);interval.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int pos,long id){if(intervals[pos]!=state.optInt("interval"))controller.action("interval",String.valueOf(intervals[pos]));}});preferences.addView(interval);
    View divider=new View(this);divider.setBackgroundColor(outline);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,1);lp.topMargin=dp(12);lp.bottomMargin=dp(14);preferences.addView(divider,lp);Switch colors=new Switch(this);colors.setText("紅漲綠跌");colors.setTextColor(text);colors.setTextSize(15);colors.setMinHeight(dp(48));colors.setChecked(state.optBoolean("redUp",true));colors.setOnCheckedChangeListener((v,checked)->controller.action("redUp",checked?"1":"0"));preferences.addView(colors);line(preferences,"關閉後採用綠漲紅跌",12,muted,false,0);
    LinearLayout markets=card(content,24);line(markets,"同步到手環的指數",16,text,true,6);line(markets,"保留至少一個指數",12,muted,false,8);Set<String> set=new HashSet<>();JSONArray selection=state.optJSONArray("selected");for(int i=0;i<selection.length();i++)set.add(selection.optString(i));JSONArray all=quotes();for(int i=0;i<all.length();i++){JSONObject q=all.optJSONObject(i);CheckBox check=new CheckBox(this);check.setText(q.optString("name")+"\n"+q.optString("region")+" · "+q.optString("symbol"));check.setTextColor(text);check.setTextSize(14);check.setMinHeight(dp(64));check.setButtonTintList(ColorStateList.valueOf(primary));check.setChecked(set.contains(q.optString("symbol")));check.setOnCheckedChangeListener((v,checked)->{if(!checked&&controller.repo.selectedSet().size()==1){v.setChecked(true);Toast.makeText(this,"至少保留一個指數",Toast.LENGTH_SHORT).show();return;}controller.action("select",q.optString("symbol")+"|"+(checked?"1":"0"));});markets.addView(check,new LinearLayout.LayoutParams(-1,-2));if(controller.repo.isCustom(q.optString("symbol"))){Button remove=button("移除 "+q.optString("symbol"),false,()->{try{controller.repo.removeCustom(q.optString("symbol"));controller.connectAndSync();render(true);}catch(Exception e){Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show();}});markets.addView(remove,new LinearLayout.LayoutParams(-1,dp(44)));}}LinearLayout about=card(content,24);line(about,"關於環球股市",16,text,true,10);line(about,"0.3.0 · 原生 Android 介面\n\n原始碼：github.com/Asternent/WristMarkets\nPolyForm Noncommercial 1.0.0\nCopyright 2026 Asternent\n\n行情由手機直接向 Yahoo Finance 取得，可能延遲。無帳號、無廣告，不讀取持倉或健康資料。\n\n背景更新可能延後；手環請求更新需要手機同步器仍在執行。",13,muted,false,0);
  }
  private String format(JSONObject q,double n,int digits){if(!Double.isFinite(n))return "—";digits=Math.max(0,Math.min(6,digits));String pattern=digits==0?"#,##0":"#,##0."+String.join("",Collections.nCopies(digits,"0"));return new DecimalFormat(pattern,DecimalFormatSymbols.getInstance(Locale.US)).format(n);}
  private String volume(JSONObject q){double n=q.optDouble("volume",Double.NaN);if(!Double.isFinite(n))return "—";return n>=100000000?format(q,n/100000000,2)+" 億":n>=10000?format(q,n/10000,2)+" 萬":format(q,n,0);}
  private String unit(JSONObject q){return "INDEX".equals(q.optString("type","INDEX"))?"點":q.optString("currency","—");}
